      '<tr><td><button class="ppmis-link" onclick="ppmis.go(\'management\',\'mix\')">Operational Resilience</button><span class="mut">8 active investments</span></td><td>Service continuity · Trusted platforms</td><td>R820m</td><td><span class="sx-bar"><i class="g" style="width:74%"></i></span> 74%</td><td>'+rag('Green')+'</td></tr>'+
      '<tr><td><button class="ppmis-link" onclick="ppmis.go(\'management\',\'mix\')">Data &amp; Insight</button><span class="mut">6 active investments</span></td><td>Information quality · Better decisions</td><td>R460m</td><td><span class="sx-bar"><i class="r" style="width:91%"></i></span> 91%</td><td>'+rag('Amber')+'</td></tr>'+
      '<tr><td><button class="ppmis-link" onclick="ppmis.go(\'management\',\'mix\')">Workforce Capability</button><span class="mut">5 active investments</span></td><td>Sustainable delivery capacity</td><td>R215m</td><td><span class="sx-bar"><i class="g" style="width:68%"></i></span> 68%</td><td>'+rag('Green')+'</td></tr></tbody></table>';
