    function row(name,start,span,type){h+='<div class="name">'+name+'</div>';for(var i=0;i<8;i++){if(i===start){h+='<div class="bar '+type+'" style="grid-column:span '+span+'">'+(type==='programme'?'Programme':'Project')+'</div>';i+=span-1;}else h+='<div class="blank"></div>';}}
