    var rows=requests.map(function(r){return '<tr class="ppmis-table-row '+(S.selected===r.id?'selected':'')+'" onclick="ppmis.select(\''+r.id+'\')"><td><b>'+r.id+'</b></td><td><button class="ppmis-link">'+r.title+'</button><span class="mut">'+r.area+'</span></td><td>'+r.driver+'</td><td>'+r.portfolio+'</td><td>'+r.cost+'</td><td>'+chip(r.stage,'stage')+'</td><td>'+rag(r.status==='Recommended'?'Green':r.status==='Information required'?'Amber':'Not started')+'</td></tr>';}).join('');
