  function costPlansView(){return card('Investment cost plans','<table class="sx-t"><thead><tr><th>Investment</th><th>Baseline</th><th>Labour</th><th>Non-labour</th><th>Actual</th><th>Forecast</th><th>Status</th></tr></thead><tbody><tr><td>Service Access Programme</td><td>R486m</td><td>R164m</td><td>R322m</td><td>R251m</td><td>R479m</td><td>'+rag('Green')+'</td></tr><tr><td>Identity Platform Renewal</td><td>R142m</td><td>R54m</td><td>R88m</td><td>R18m</td><td>R146m</td><td>'+rag('Amber')+'</td></tr><tr><td>Case Data Remediation</td><td>R54m</td><td>R31m</td><td>R23m</td><td>R41m</td><td>R62m</td><td>'+rag('Red')+'</td></tr></tbody></table>','Baseline, actual and forecast costs stay connected to each investment')+'<div class="sx-actions"><button class="sx-btn primary" onclick="ppmis.notify(\'Financial baseline captured with version and approval reference.\')">Create baseline</button></div>';}
  function forecastsView(){return card('Forecast changes','<table class="sx-t"><thead><tr><th>Investment</th><th>Previous</th><th>Current</th><th>Movement</th><th>Reason</th><th>Decision impact</th></tr></thead><tbody><tr><td>Case Data Remediation</td><td>R54m</td><td>R62m</td><td class="r">+R8m</td><td>Recovery team and extended testing</td><td>Executive approval required</td></tr><tr><td>Service Access Programme</td><td>R486m</td><td>R479m</td><td class="g">−R7m</td><td>Procurement saving</td><td>R7m may be reallocated</td></tr><tr><td>Digital Foundations Programme</td><td>R620m</td><td>R611m</td><td class="g">−R9m</td><td>Hosting agreement revised</td><td>No change to scope</td></tr></tbody></table>','Forecast movements feed portfolio affordability and scenario decisions');}

